//! Read-only artwork sampling through the production palette/rendition path.
use anyhow::{Context,Result};
fn main()->Result<()>{let path=std::env::args_os().nth(1).context("Pass an artwork image")?;let path=std::path::Path::new(&path);let start=std::time::Instant::now();let grid_ms=if std::env::args().any(|arg|arg=="--warm-grid"){musicos_tauri::artwork_renditions::rendition(path,640)?;Some(start.elapsed().as_secs_f64()*1000.)}else{None};let start=std::time::Instant::now();let first=musicos_tauri::providers::palette(path)?;let cold_ms=start.elapsed().as_secs_f64()*1000.;let start=std::time::Instant::now();let second=musicos_tauri::providers::palette(path)?;println!("{}",serde_json::json!({"source_bytes":path.metadata()?.len(),"palette":first,"repeat_palette":second,"grid_prepare_ms":grid_ms,"first_ms":cold_ms,"cached_ms":start.elapsed().as_secs_f64()*1000.}));Ok(())}
